import { lazy, Suspense, useEffect, useRef, useState } from "react";
import { cn } from "../../lib/cn";

// lottie-web is ~200 KB gzipped, so the player and each animation load on
// first use instead of landing in the main bundle. Only pages that show an
// animation (landing, payment success) ever download it.
const Lottie = lazy(() => import("lottie-react").then((m) => ({ default: m.Lottie })));

// Lottie files live in src/assets/lottie and are generated by
// scripts/build-lottie.mjs (`npm run lottie`). Add new ones to this map.
const ANIMATIONS = {
  heartbeat: () => import("../../assets/lottie/heartbeat.json"),
  typing: () => import("../../assets/lottie/typing.json"),
  "match-ring": () => import("../../assets/lottie/match-ring.json"),
  "success-burst": () => import("../../assets/lottie/success-burst.json"),
};

/**
 * <Animation name="typing" className="h-[30px] w-14" />
 *
 * Size it with className; the animation fills the box. Decorative by default
 * (hidden from screen readers); pass `label` when it carries meaning.
 * With prefers-reduced-motion, lottie-react skips autoplay and shows frame 0;
 * `restAt` (0-100) picks a better still frame for animations whose first
 * frame is empty, e.g. a ring that fills up.
 */
export default function Animation({ name, loop = true, restAt, label, className }) {
  const [data, setData] = useState(null);
  const lottieRef = useRef(null);

  useEffect(() => {
    let active = true;
    ANIMATIONS[name]().then((module) => active && setData(module.default));
    return () => {
      active = false;
    };
  }, [name]);

  const onReady = () => {
    if (restAt !== undefined && window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      lottieRef.current?.seek({ percent: restAt });
    }
  };

  const a11y = label ? { role: "img", "aria-label": label } : { "aria-hidden": true };
  const box = cn("pointer-events-none", className);
  const placeholder = <span className={cn("block", box)} {...a11y} />;

  if (!data) return placeholder;
  return (
    <Suspense fallback={placeholder}>
      <Lottie src={data} autoplay loop={loop} lottieRef={lottieRef} subscriptions={{ ready: onReady }} className={box} {...a11y} />
    </Suspense>
  );
}
